function App() {
  const [log, setLog] = useState([]);
  const wait = (ms, label) => new Promise(r => setTimeout(() => r(label), ms));
  const run = async () => {
    setLog(['running…']);
    const t0 = Date.now();
    // Sequential (waterfall)
    await wait(700, 'A'); await wait(700, 'B');
    const seq = Date.now() - t0;
    const t1 = Date.now();
    // Parallel
    await Promise.all([wait(700, 'A'), wait(700, 'B')]);
    const par = Date.now() - t1;
    setLog([`Sequential: ~${seq}ms`, `Parallel (Promise.all): ~${par}ms`]);
  };
  return (
    <div style={{ fontFamily: 'system-ui', padding: 16 }}>
      <button onClick={run}>Run comparison</button>
      <ul>{log.map((l, i) => <li key={i}>{l}</li>)}</ul>
    </div>
  );
}

