function App() {
  // Fix: opt out of caching for live data.
  const code = [
    "export default async function Dashboard() {",
    "  const stats = await fetch('/api/stats', {",
    "    cache: 'no-store',            // always fresh (dynamic)",
    "  }).then(r => r.json());",
    "  // Or: { next: { revalidate: 10 } } for ~10s freshness",
    "  return <Stats data={stats} />;",
    "}",
  ];
  return (<pre style={{ fontFamily: 'ui-monospace, monospace', padding: 16, fontSize: 12 }}>{code.join('\n')}</pre>);
}

// app/products/[id]/page.tsx (Server Component)
import { ProductView } from './ProductView'; // 'use client'

export default async function Page({ params }: { params: { id: string } }) {
  const [product, reviews] = await Promise.all([
    fetch(`https://api/products/${params.id}`, {
      next: { revalidate: 60 },          // ISR: refresh every 60s
    }).then((r) => r.json()),
    fetch(`https://api/products/${params.id}/reviews`, {
      cache: 'no-store',                 // always fresh
    }).then((r) => r.json()),
  ]);

  return <ProductView product={product} reviews={reviews} />;
}
